// Accepts { id?, source?, raw_message } from any channel and produces one clean message.
const body = $input.first().json.body ?? {};
const raw = typeof body.raw_message === 'string' ? body.raw_message.trim() : '';

return [{
  json: {
    id: body.id ?? `ARC-${$execution.id}`,
    source: typeof body.source === 'string' && body.source.trim() ? body.source.trim() : 'Unknown',
    received_at: new Date().toISOString(),
    raw_message: raw,
    // Stops a customer from closing the delimiter tag that marks their text as data.
    prompt_message: raw.replace(/<\/?customer_message>/gi, ''),
    valid: raw.length > 0,
  },
}];

// Never trust LLM output: check every field. Invalid output is marked, then sent to a human.
const CATEGORIES = ['Bug Report', 'Feature Request', 'Billing Issue', 'Technical Question', 'Incident/Outage'];
const PRIORITIES = ['Low', 'Medium', 'High'];

function parseLlmJson(response) {
  try {
    return JSON.parse(response.choices[0].message.content);
  } catch (e) {
    return null;
  }
}

function normalizeConfidence(value) {
  const isPercent = typeof value === 'string' && value.includes('%');
  const n = typeof value === 'number' ? value : parseFloat(value);
  if (!Number.isFinite(n) || n < 0 || n > 100) return null;
  return isPercent || n > 1 ? n / 100 : n;
}

const parsed = parseLlmJson($input.first().json);
const category = CATEGORIES.find((c) => c === parsed?.category);
const priority = PRIORITIES.find((p) => p === parsed?.priority);
const confidence = normalizeConfidence(parsed?.confidence);
const valid = Boolean(category && priority && confidence !== null);

return [{
  json: {
    ...$('Normalize Input').first().json,
    classification: {
      category: valid ? category : 'Unclassified',
      priority: valid ? priority : 'Medium',
      confidence: valid ? confidence : 0,
      reasoning: typeof parsed?.reasoning === 'string' ? parsed.reasoning : '',
    },
    classification_valid: valid,
  },
}];

// Keeps only values that really appear in the message, so a made-up ID can't reach a team.
function parseLlmJson(response) {
  try {
    return JSON.parse(response.choices[0].message.content);
  } catch (e) {
    return null;
  }
}

const previous = $('Validate Classification').first().json;
const message = previous.raw_message;
const lowerMessage = message.toLowerCase();
const digitsOnlyMessage = message.replace(/,/g, '');
const parsed = parseLlmJson($input.first().json);

function literalValues(values) {
  if (!Array.isArray(values)) return [];
  const strings = values.filter((v) => typeof v === 'string' && v.trim());
  return [...new Set(strings.filter((v) => lowerMessage.includes(v.toLowerCase())))];
}

// Returns the amount only when that number is in the message (so "1,240" matches 1240).
function verifiedAmount(value) {
  if (value === null || value === undefined) return { amount: null, rejected: false };
  const n = typeof value === 'number' ? value : parseFloat(String(value).replace(/[$,]/g, ''));
  if (!Number.isFinite(n) || n < 0) return { amount: null, rejected: true };
  const pattern = new RegExp(`(^|[^\\d.])${String(n).replace('.', '\\.')}(\\.0+)?(?![\\d])`);
  return pattern.test(digitsOnlyMessage) ? { amount: n, rejected: false } : { amount: null, rejected: true };
}

function buildBilling(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const charged = verifiedAmount(raw.charged_amount);
  const expected = verifiedAmount(raw.expected_amount);
  const stated = verifiedAmount(raw.stated_discrepancy);

  let discrepancy = stated.amount;
  if (discrepancy === null && charged.amount !== null && expected.amount !== null) {
    discrepancy = Math.round(Math.abs(charged.amount - expected.amount) * 100) / 100;
  }
  return {
    charged_amount: charged.amount,
    expected_amount: expected.amount,
    discrepancy,
    amounts_verified: !(charged.rejected || expected.rejected || stated.rejected),
  };
}

const URGENCY = ['Low', 'Medium', 'High'];
const hasIssue = typeof parsed?.core_issue === 'string' && parsed.core_issue.trim().length > 0;
const hasUrgency = URGENCY.includes(parsed?.urgency);
const ids = parsed?.identifiers ?? {};

return [{
  json: {
    ...previous,
    enrichment: {
      core_issue: hasIssue ? parsed.core_issue.trim() : 'Could not be extracted automatically; see the raw message.',
      urgency: hasUrgency ? parsed.urgency : 'Medium',
      urgency_reason: typeof parsed?.urgency_reason === 'string' ? parsed.urgency_reason : '',
      identifiers: {
        account_ids: literalValues(ids.account_ids),
        invoice_numbers: literalValues(ids.invoice_numbers),
        error_codes: literalValues(ids.error_codes),
        other: literalValues(ids.other),
      },
      timeframe: typeof parsed?.timeframe === 'string' && parsed.timeframe.trim() ? parsed.timeframe.trim() : null,
      billing: buildBilling(parsed?.billing),
    },
    enrichment_valid: hasIssue && hasUrgency,
  },
}];

// Deterministic on purpose: the same facts always give the same queue, and a customer
// message can't talk the model into a route. Thresholds live here, in one place.
const CONFIDENCE_THRESHOLD = 0.7;
const BILLING_ESCALATION_USD = 500;
const ESCALATION_QUEUE = 'Human Escalation';

const QUEUE_BY_CATEGORY = {
  'Bug Report': 'Engineering',
  'Feature Request': 'Product',
  'Billing Issue': 'Billing',
  'Technical Question': 'IT/Security',
  'Incident/Outage': 'Engineering',
};

// Whole words only, so "download" doesn't match "down".
const OUTAGE_PHRASES = /\boutage\b|\bdown for (all users|everyone|all of us)\b/i;

const record = $input.first().json;
const { classification, enrichment, raw_message: message } = record;
const billing = enrichment.billing;
const reasons = [];

if (!record.classification_valid) reasons.push('classification_invalid');
if (!record.enrichment_valid) reasons.push('enrichment_invalid');

if (record.classification_valid && classification.confidence < CONFIDENCE_THRESHOLD) {
  reasons.push('low_confidence');
}
if (classification.category === 'Incident/Outage') reasons.push('incident_category');
if (OUTAGE_PHRASES.test(message)) reasons.push('outage_language');

if (billing) {
  if (billing.discrepancy !== null && billing.discrepancy > BILLING_ESCALATION_USD) {
    reasons.push('billing_discrepancy_over_500');
  } else if (
    billing.discrepancy === null &&
    (!billing.amounts_verified || (billing.charged_amount ?? 0) > BILLING_ESCALATION_USD)
  ) {
    // No baseline to compare against, so a person has to judge the size of the error.
    reasons.push('billing_amount_unverified');
  }
}

const suggestedQueue = QUEUE_BY_CATEGORY[classification.category] ?? 'Unassigned';
const escalated = reasons.length > 0;

return [{
  json: {
    ...record,
    routing: {
      suggested_queue: suggestedQueue,
      final_queue: escalated ? ESCALATION_QUEUE : suggestedQueue,
      escalated,
      escalation_reasons: reasons,
    },
  },
}];

// Assembles the final record. If the summary step fails, a template keeps the record usable.
const triage = $('Route & Escalate').first().json;
const config = $('Prompts & Config').first().json;

function parseSummary(response) {
  try {
    const summary = JSON.parse(response.choices[0].message.content).summary;
    return typeof summary === 'string' && summary.trim() ? summary.trim() : null;
  } catch (e) {
    return null;
  }
}

// Keeps only named text fields, never the whole error object, because that can hold request
// headers and therefore the API key.
function llmError(nodeName) {
  const error = $(nodeName).first().json.error;
  if (!error) return null;
  const parts = typeof error === 'string'
    ? [error]
    : [error.httpCode, error.message, error.description, error.error?.message];
  const text = parts.filter(Boolean).join(' | ');
  return (text || safeDump(error)).slice(0, 500);
}

// For errors with no named fields: drops anything that could carry credentials, then redacts keys.
function safeDump(error) {
  const dropped = /header|config|request|auth|token|key|secret|cookie/i;
  const json = JSON.stringify(error, (name, value) => (dropped.test(name) ? undefined : value));
  return (json ?? 'unknown error').replace(/gsk_\w+/g, '[redacted]').replace(/Bearer\s+\S+/gi, '[redacted]');
}

const { classification, enrichment, routing } = triage;
const llmSummary = parseSummary($input.first().json);
const fallbackSummary =
  `${enrichment.core_issue} Classified as ${classification.category} with ${classification.priority} priority. ` +
  (routing.escalated
    ? `A person must review this ticket: ${routing.escalation_reasons.join(', ')}.`
    : `Please review it in the ${routing.final_queue} queue.`);

const record = {
  id: triage.id,
  source: triage.source,
  received_at: triage.received_at,
  raw_message: triage.raw_message,
  classification,
  enrichment,
  routing,
  summary: llmSummary ?? fallbackSummary,
  metadata: {
    model: config.model,
    prompt_version: config.prompt_version,
    workflow_version: config.workflow_version,
    summary_source: llmSummary ? 'llm' : 'template_fallback',
    llm_errors: {
      classify: llmError('Classify (LLM)'),
      enrich: llmError('Enrich (LLM)'),
      summarize: llmError('Summarize (LLM)'),
    },
    processed_at: new Date().toISOString(),
  },
};

const ids = enrichment.identifiers;
const row = {
  id: record.id,
  source: record.source,
  received_at: record.received_at,
  category: classification.category,
  priority: classification.priority,
  confidence: classification.confidence,
  core_issue: enrichment.core_issue,
  urgency: enrichment.urgency,
  account_ids: ids.account_ids.join(', '),
  invoice_numbers: ids.invoice_numbers.join(', '),
  error_codes: ids.error_codes.join(', '),
  other_references: ids.other.join(', '),
  timeframe: enrichment.timeframe ?? '',
  billing_discrepancy: enrichment.billing?.discrepancy ?? '',
  suggested_queue: routing.suggested_queue,
  final_queue: routing.final_queue,
  escalated: routing.escalated,
  escalation_reasons: routing.escalation_reasons.join(', '),
  summary: record.summary,
  raw_message: record.raw_message,
};

return [{ json: { ...row, record } }];
